#!/usr/bin/env bash
# JVM unit tests for the pure logic (no Android, no device). Usage: test/run.sh <jdk-home>
set -euo pipefail
JDK="${1:?usage: test/run.sh <jdk-home>}"
cd "$(dirname "$0")/.."
OUT=build/test-classes; rm -rf "$OUT"; mkdir -p "$OUT"
"$JDK/bin/javac" -d "$OUT" ../android/app/src/main/java/com/rasha/omni/Accordion.java ../android/app/src/main/java/com/rasha/omni/SpringMath.java \
    ../android/app/src/main/java/com/rasha/omni/ListOps.java ../android/app/src/main/java/com/rasha/omni/AppFilter.java ../android/app/src/main/java/com/rasha/omni/CategoryRules.java ../android/app/src/main/java/com/rasha/omni/DeviceTypes.java ../android/app/src/main/java/com/rasha/omni/PtvRules.java ../android/app/src/main/java/com/rasha/omni/WeatherCodes.java ../android/app/src/main/java/com/rasha/omni/NetKind.java ../android/app/src/main/java/com/rasha/omni/PtvModel.java ../android/app/src/main/java/com/rasha/omni/PtvSearch.java ../android/app/src/main/java/com/rasha/omni/PtvUsage.java ../android/app/src/main/java/com/rasha/omni/ChannelSort.java ../android/app/src/main/java/com/rasha/omni/PreviewPolicy.java ../android/app/src/main/java/com/rasha/omni/Dominant.java ../android/app/src/main/java/com/rasha/omni/LumaVeil.java ../android/app/src/main/java/com/rasha/omni/WallpaperRules.java ../android/app/src/main/java/com/rasha/omni/WeatherFormat.java ../android/app/src/main/java/com/rasha/omni/ControlRows.java ../android/app/src/main/java/com/rasha/omni/SearchHit.java ../android/app/src/main/java/com/rasha/omni/EventRules.java ../android/app/src/main/java/com/rasha/omni/SetupFlow.java ../android/app/src/main/java/com/rasha/omni/Intents.java ../android/app/src/main/java/com/rasha/omni/KeyMap.java ../android/app/src/main/java/com/rasha/omni/CrashRules.java ../android/app/src/main/java/com/rasha/omni/UpdateRules.java ../android/app/src/main/java/com/rasha/omni/HdmiRules.java test/com/rasha/omni/*.java
"$JDK/bin/java" -cp "$OUT" com.rasha.omni.RunAll
